 public static void main(String[]args){ok(Parkour20.heightAllowed(2)&&!Parkour20.heightAllowed(2.01)&&Parkour20.heightAllowed(.5),"donor two-block cap retained");Player p=jumper(2);ok(Move25.request(p,3)&&Parkour20.active(p),"second jump action starts mantle at a valid two-block ledge");int ticks=0;while(Parkour20.active(p)&&ticks++<35){Parkour20.tick(p,true);p.step();}ok(!Parkour20.active(p)&&p.py>=2&&Math.abs(p.pz-1.5)<.20,"climb actually reaches top using collision-checked motion");ok(ticks<=28,"bounded mantle duration");
 Player tall=jumper(3);Move25.request(tall,3);ok(!Parkour20.active(tall),"three-block wall rejected");Player ceiling=jumper(2);ceiling.physics.blocks.put(new BlockPos(0,3,1),new Block(true));Move25.request(ceiling,3);ok(!Parkour20.active(ceiling),"blocked headroom rejected");Player unloaded=jumper(2);unloaded.physics.loaded=false;Move25.request(unloaded,3);ok(!Parkour20.active(unloaded),"does not load chunks to find ledge");Player grounded=jumper(2);grounded.ground=true;Move25.request(grounded,3);ok(!Parkour20.active(grounded),"no standing mantle without a jump");
 Player slide=new Player();slide.sprinting=true;Slide20.tick(slide);slide.pz+=.2;slide.physics.time++;Slide20.tick(slide);ok(Move25.request(slide,2)&&Slide20.STATES.containsKey(slide)&&slide.forced==Pose.SWIMMING,"run then crouch starts actual slide");double initial=Slide20.STATES.get(slide).speed;Slide20.tick(slide);ok(slide.velocity.z>0&&slide.velocity.z<initial&&slide.velocity.y==0,"slide decays horizontally without vertical boost");int cues=PacketDistributor.cues.size();Move25.request(slide,2);ok(PacketDistributor.cues.size()==cues,"active slide cannot be restarted to gain speed");slide.horizontalCollision=true;Slide20.tick(slide);ok(!Slide20.STATES.containsKey(slide)&&slide.forced==null,"collision stops slide and restores pose");Move25.request(slide,2);ok(!Slide20.STATES.containsKey(slide),"cooldown blocks immediate repeat");Player still=new Player();still.sprinting=true;Slide20.tick(still);Move25.request(still,2);ok(!Slide20.STATES.containsKey(still),"stationary sprint flag cannot fabricate momentum");
 Player server=jumper(2);Move25.request(server,3);Player client=new Player();client.physics.wall(2);client.ground=false;client.py=.4;client.physics.client=true;client.twin=server;Minecraft.INSTANCE.player=client;Minecraft.INSTANCE.level=client.physics;Parkour20.GROUND.put(client,new double[]{0,100});Parkour20.accept(client,true);ok(Parkour20.active(client)&&Parkour20.ACTIVE.get(client)!=Parkour20.ACTIVE.get(server),"same-ID client prediction does not overwrite server state");int age=Parkour20.ACTIVE.get(server).age;Parkour20.tick(client,false);ok(Parkour20.ACTIVE.get(server).age==age,"client tick does not advance server mantle");SideMap25.clearClient();ok(!Parkour20.active(client)&&Parkour20.active(server),"world/client reset preserves authoritative mantle");cues=PacketDistributor.cues.size();Move25.tick(new Tick(client));Move25.request(client,2);ok(PacketDistributor.cues.size()==cues,"client cannot broadcast movement packets");
 Player dimension=jumper(2);Move25.request(dimension,3);dimension.physics.dim="nether";Parkour20.tick(dimension,true);ok(!Parkour20.active(dimension),"dimension change cancels mantle");
 Player network=jumper(2);ProtocolChecks18.Register registration=new ProtocolChecks18.Register();Net20.register(registration);Context context=new Context(network);registration.r.handler.handle(new Heavy18(-1,3),context);ok(context.task!=null&&!Parkour20.active(network),"movement network handler queues work without touching world on network thread");context.task.run();ok(Parkour20.active(network),"queued action 3 routes through Combat18 to mantle");
 Minecraft mc=Minecraft.INSTANCE;Player input=new Player();input.physics.client=true;input.physics.wall(2);input.physics.entities.put(50,input);input.sprinting=true;mc.player=input;mc.level=input.physics;mc.screen=null;long[]clock={5_000_000_000L};BoxingClient16.CLOCK=()->clock[0];MoveClient25.tick();clock[0]+=50_000_000L;input.pz+=.2;MoveClient25.tick();clock[0]+=50_000_000L;input.pz+=.2;mc.options.keyShift.down=true;PacketDistributor.sent=null;MoveClient25.tick();ok(PacketDistributor.sent instanceof Heavy18 packet&&packet.action()==2,"run plus fresh crouch key sends slide request");Object sent=PacketDistributor.sent;clock[0]+=50_000_000L;input.pz+=.2;MoveClient25.tick();ok(PacketDistributor.sent==sent,"held crouch does not spam slide requests");MoveClient25.receive(50,115);ok(Slide20.CLIENT.containsKey(input)&&input.forced==Pose.SWIMMING,"server slide cue starts local prediction");MoveClient25.receive(50,99);ok(input.forced==null&&!Slide20.CLIENT.containsKey(input),"stop cue restores local pose");mc.options.keyShift.down=false;input.pz=.5;MoveClient25.tick();mc.options.keyJump.down=true;clock[0]+=50_000_000L;PacketDistributor.sent=null;MoveClient25.tick();ok(PacketDistributor.sent==null,"first jump remains a normal jump");input.ground=false;input.py=.4;mc.options.keyJump.down=false;clock[0]+=50_000_000L;MoveClient25.tick();mc.options.keyJump.down=true;clock[0]+=50_000_000L;MoveClient25.tick();ok(PacketDistributor.sent instanceof Heavy18 packet&&packet.action()==3,"second jump edge sends climb request");mc.screen=new Object();PacketDistributor.sent=null;mc.options.keyJump.down=false;MoveClient25.tick();mc.options.keyJump.down=true;MoveClient25.tick();ok(PacketDistributor.sent==null,"menus suppress movement input");mc.screen=null;
 Parkour20.accept(input,true);Parkour20.tick(input,false);Parkour20.tick(input,false);Parkour20.tick(input,false);var posed=new net.minecraft.client.model.PlayerModel<Object>();posed.rightArm=new net.minecraft.client.model.geom.ModelPart();posed.leftArm=new net.minecraft.client.model.geom.ModelPart();posed.rightSleeve=new net.minecraft.client.model.geom.ModelPart();posed.leftSleeve=new net.minecraft.client.model.geom.ModelPart();posed.body=new net.minecraft.client.model.geom.ModelPart();posed.rightLeg=new net.minecraft.client.model.geom.ModelPart();posed.leftLeg=new net.minecraft.client.model.geom.ModelPart();ok(MoveClient25.body(posed,input)&&posed.rightArm.xRot<-2&&posed.rightSleeve.xRot==posed.rightArm.xRot,"mantle poses arms and sleeves together");MoveClient25.receive(50,201);ok(!Parkour20.active(input)&&!MoveClient25.body(posed,input),"mantle stop releases body override");
 for(int i=0;i<=20;i++){ok(Slide20.speed(.4,i)<=.4&&Slide20.duration(i*.03)<=22&&Slide20.duration(i*.03)>=8,"bounded slide speed and duration");}System.out.println("TWO_BLOCK_MANTLE_COLLISION_HEADROOM_SLIDE_POSE_COOLDOWN_SIDE_ISOLATION_CHECKS="+checks);}
